import { useState } from 'react';

export default function Stepper() {
  const [value, setValue] = useState(0);

  return (
    <>
      <p>Value: {value}</p>
      <button onClick={() => setValue((v) => v + 5)}>+5</button>
      <button onClick={() => setValue(0)} disabled={value === 0}>
        Reset
      </button>
    </>
  );
}

