exercises.solutionCode:
const books = [
  { isbn: '978-0', title: 'Refactoring', pages: 448 },
  { isbn: '978-1', title: 'The Pragmatic Programmer', pages: 352 },
  { isbn: '978-2', title: 'Clean Code', pages: 464 },
  { isbn: '978-3', title: 'Short Guide', pages: 120 },
];

export default function LongBooks() {
  const long = books.filter((book) => book.pages > 300);

  if (long.length === 0) return <p>No long books</p>;

  return (
    <ul>
      {long.map((book) => (
        <li key={book.isbn}>{book.title}</li>
      ))}
    </ul>
  );
}

